After look into this issue in depth

> Allow a maximum export depth to be specified in the webpack config for JSON files
webpack 4 only computed top-level exports for JSON:
[v4.47.0/lib/JsonParser.js#L20](https://github.com/webpack/webpack/blob/v4.47.0/lib/JsonParser.js#L20) 

I found It will make json `untreeshakable` and its key `unmangled` in production mode.

for example

```
// data.json
{
  "used": "used",
  "unused": "unused",
  "nested": {
    "used": "used",
    "unused": "unused",
    "nested": {
      "used": "used",
      "unused": "unused",
      "nested": {
        "used": "used",
        "unused": "unused",
        "nested": {
          "used": "used",
          "unused": "unused",
          "nested": { "used": "used", "unused": "unused" },
          "depth": 5
        },
        "depth": 4
      },
      "depth": 3
    },
    "depth": 2
  },
  "depth": 1
}

// index.js
import data from './data.json';
console.log(data.nested.nested.nested.nested.nested.used);
```

output with treeshaking and mangle
```js
(()=>{"use strict";const c=JSON.parse('{"cY":{"cY":{"cY":{"cY":{"cY":{"k":"used"}}}}}}');console.log(c.cY.cY.cY.cY.cY.k)})();
```


output without treeshaking and mangle when limit json nested depth
```js
(() => { "use strict"; const e = JSON.parse('{"cY":{"used":"used","unused":"unused","nested":{"used":"used","unused":"unused","nested":{"used":"used","unused":"unused","nested":{"used":"used","unused":"unused","nested":{"used":"used","unused":"unused"},"depth":5},"depth":4},"depth":3},"depth":2}}'); console.log(e.cY.nested.nested.nested.nested.used) })();
```

because we consume its exportsInfo in `FlagDependencyUsagePlugin`

https://github.com/webpack/webpack/blob/3612d36e44bda5644dc3b353e2cade7fe442ba59/lib/FlagDependencyUsagePlugin.js#L97

maybe we can adopt it in `development` mode? But it will cause `JsonExportsDependency` to be coupled to `options.mode` that I don't think it's appropriate.
